def collect_results(tasks):
    grouped = {}
    for task in tasks:
        status = task['status']
        if status not in grouped:
            grouped[status] = []
        grouped[status].append(task['id'])
    return grouped

def batch_for_gather(items, size):
    if size <= 0:
        return []
    return [items[i:i + size] for i in range(0, len(items), size)]

def estimate_async_gain(latencies_ms):
    if not latencies_ms:
        return {'sync_total_ms': 0, 'ideal_async_ms': 0}
    return {
        'sync_total_ms': sum(latencies_ms),
        'ideal_async_ms': max(latencies_ms),
    }

def choose_execution_style(wait_ms, cpu_heavy):
    if not cpu_heavy and wait_ms >= 10:
        return 'async'
    return 'sync'

