class TaskScheduler:
    def __init__(self, max_concurrent):
        self._max = max_concurrent
        self._pending = []
        self._done = []

    def submit(self, name, duration_ms):
        self._pending.append({'name': name, 'duration_ms': duration_ms})
        return self

    def next_batch(self):
        batch = sorted(self._pending, key=lambda t: t['duration_ms'])[:self._max]
        return [t['name'] for t in batch]

    def complete(self, name):
        for task in self._pending:
            if task['name'] == name:
                self._pending = [t for t in self._pending if t['name'] != name]
                self._done.append(name)
                return True
        return False

    def stats(self):
        return {'pending': len(self._pending), 'done': len(self._done), 'capacity': self._max}
